    <div class="onboarding__content">
      <h1 class="onboarding__title">Как это работает?</h1>
      <p class="onboarding__text">
        Выбирайте и бронируйте товары через
        мобильное приложение — а <strong>забирайте</strong> их
        быстро и удобно в наших <strong>офлайн-магазинах.</strong>
      </p>
    </div>

  <div class="onboarding__footer">
      <div class="onboarding__dots">
        <span
          v-for="(route, index) in routes"
          :key="index"
          class="dot"
          :class="{ 'dot--active': index === currentIndex }"
          @click="goTo(route)"
        />
      </div>
      <button class="onboarding__btn" @click="goNext">
        <svg width="22" height="22" viewBox="0 0 24 24" fill="none">
          <path d="M5 12H19M14 7l5 5-5 5" stroke="#111D33" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
        </svg>
      </button>
    </div>
  </div>
</template>

<script setup>
import { useRouter } from 'vue-router'

const router = useRouter()
const currentIndex = 0 // вторая точка активна (0-based)
 
const routes = [
  '/onboarding/1',
  '/onboarding/2',
  '/onboarding/3',
  '/onboarding/4',
]
 
const goTo = (route) => {
  router.push(route)
}
 
const goNext = () => {
  router.push('/onboarding/3')
}
</script>

<style scoped>
@import url('https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600&display=swap');

.onboarding {
  width: 100%;
  height: 100vh;
  display: flex;
  flex-direction: column;
  background: #ffffff;
  overflow: hidden;
  font-family: 'Manrope', sans-serif;
  animation: fadeIn 0.45s ease both;
}

